steps.text:
/*
	VIOC_ai_allies.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "ai_allied_skill": la IA de tu bando pelea mejor; la del enemigo queda igual que siempre.

	- "Tu bando" = cada bando (oeste o este) que tiene al menos un jugador humano. Se revisa en cada pasada;
	  un bando que ya tuvo un jugador no pierde la mejora (por ejemplo mientras reapareces).
	  Nunca toca a los jugadores, a la guerrilla de los pueblos (resistance) ni a los civiles.
	- Parametro de lobby VIOC_AI_ALLY_SKILL (habilidad):
	    0 = igual que el enemigo (original), 1 = un poco mejor, 2 = mejorada (por defecto), 3 = elite.
	  Sube cada habilidad por separado (tabla VIOC_ALLY_PROFILES): sobre todo detectar, reaccionar, avisar al
	  grupo, valor y recarga; apuntar algo mas rapido y la punteria solo un poco. Cada valor varia +-0.05 entre
	  soldados y nunca baja lo que la unidad ya tenia (si subes "AI: Skill" en el lobby, queda el mayor).
	- Parametro de lobby VIOC_AI_ALLY_NOFLEE: 1 = los grupos IA de tu bando nunca huyen (allowFleeing 0, como
	  los defensores de los pueblos; por defecto), 0 = original. Los grupos con jugadores no se tocan.
	- Cada unidad se procesa una sola vez: al nacer (linea agregada en Common\Functions\Common_CreateUnit.sqf)
	  o en la pasada cada 20 s, que agarra al resto (lideres de los equipos IA, lideres reaparecidos,
	  tripulaciones de drones y de defensas antiaereas, obreros). La marca guarda la propia unidad, asi que un
	  lider que reaparece (cuerpo nuevo) se vuelve a procesar aunque Arma le copie las variables del anterior.
	- "Nunca huye" se repite en cada pasada, asi cubre a los refuerzos que llegan despues y a los lideres nuevos.
	- Corre en cada maquina y solo toca sus unidades locales (setSkill solo funciona en la maquina duena de la
	  unidad). En una partida alojada todo es local a tu PC.
	- No cambia CTI_AI_SKILL_BASE (de el depende el precio de 1/100 que paga la IA) ni nada del enemigo.
	- Consola de depuracion: VIOC_ALLY_STATUS = [nivel, sin huida, bandos humanos, unidades procesadas,
	  grupos sin huida en la ultima pasada].
*/
if (!isNil "VIOC_ALLY_STARTED") exitWith {};
VIOC_ALLY_STARTED = true;

//--- Parametros de lobby (en "Un jugador" la mision no los carga: valen los de por defecto).
VIOC_ALLY_LEVEL = missionNamespace getVariable ["VIOC_AI_ALLY_SKILL", 2];
if !(VIOC_ALLY_LEVEL isEqualType 0) then {VIOC_ALLY_LEVEL = 2};
VIOC_ALLY_LEVEL = ((round VIOC_ALLY_LEVEL) max 0) min 3;
VIOC_ALLY_NOFLEE = missionNamespace getVariable ["VIOC_AI_ALLY_NOFLEE", 1];
if !(VIOC_ALLY_NOFLEE isEqualType 0) then {VIOC_ALLY_NOFLEE = 1};
VIOC_ALLY_NOFLEE = VIOC_ALLY_NOFLEE > 0;

if (VIOC_ALLY_LEVEL == 0 && {!VIOC_ALLY_NOFLEE}) exitWith {
	diag_log "VIOC_ai_allies: desactivado (VIOC_AI_ALLY_SKILL = 0 y VIOC_AI_ALLY_NOFLEE = 0).";
};

//--- Valores de setSkill por nivel, en este orden ("general" primero, las demas habilidades despues).
//--- Referencia: la mision le da a todos 0.30-0.50 en todo (lobby "AI: Skill" 30%). Con el nivel de IA "Experto"
//--- (skillAI 0.8 / precisionAI 0.7) eso es 0.50-0.64 de deteccion final y 0.43-0.58 de punteria final.
//--- Nivel 2: deteccion final ~0.83, reaccion ~0.80, punteria ~0.58 (la del mejor soldado enemigo).
//--- No subas aimingAccuracy por encima de ~0.65: con mas, la IA empieza a acertar "como laser".
VIOC_ALLY_PROFILES = [
	[],
	[["general",0.55],["spotDistance",0.60],["spotTime",0.58],["commanding",0.58],["courage",0.60],["reloadSpeed",0.58],["aimingSpeed",0.50],["aimingAccuracy",0.45],["aimingShake",0.45]],
	[["general",0.70],["spotDistance",0.80],["spotTime",0.75],["commanding",0.75],["courage",0.80],["reloadSpeed",0.75],["aimingSpeed",0.60],["aimingAccuracy",0.50],["aimingShake",0.50]],
	[["general",0.80],["spotDistance",0.90],["spotTime",0.85],["commanding",0.85],["courage",0.90],["reloadSpeed",0.85],["aimingSpeed",0.75],["aimingAccuracy",0.60],["aimingShake",0.60]]
];
VIOC_ALLY_PROFILE = VIOC_ALLY_PROFILES select VIOC_ALLY_LEVEL;
VIOC_ALLY_JITTER = 0.05;	//--- variacion entre soldados (+-)
VIOC_ALLY_PERIOD = 20;		//--- segundos entre pasadas
VIOC_ALLY_SIDES = [];
VIOC_ALLY_UNITS = 0;
VIOC_ALLY_GROUPS = 0;
VIOC_ALLY_STATUS = [VIOC_ALLY_LEVEL, VIOC_ALLY_NOFLEE, VIOC_ALLY_SIDES, VIOC_ALLY_UNITS, VIOC_ALLY_GROUPS];

//--- Bandos (oeste/este) con algun jugador humano vivo. Solo se agregan, nunca se quitan.
VIOC_fnc_allySides = {
	private _players = allPlayers;
	if (!isMultiplayer && {hasInterface} && {!isNull player}) then {_players pushBackUnique player};
	{
		if (alive _x && {!(_x isKindOf "HeadlessClient_F")}) then {
			private _side = side group _x;
			if ((_side in [west, east]) && {!(_side in VIOC_ALLY_SIDES)}) then {
				VIOC_ALLY_SIDES pushBack _side;
				diag_log format ["VIOC_ai_allies: bando con jugador humano: %1 (habilidad %2, sin huida %3)", _side, VIOC_ALLY_LEVEL, VIOC_ALLY_NOFLEE];
			};
		};
	} forEach _players;
	VIOC_ALLY_SIDES
};

//--- Mejora una unidad IA local de un bando humano, una sola vez por cuerpo. Devuelve true si la proceso.
//--- Lee todos los valores actuales antes de cambiar nada: poner "general" puede arrastrar a las demas habilidades.
//--- aimingSpeed toma "general" como piso: su curva de CfgAISkill no es 1:1 y "skill" podria devolverla convertida.
VIOC_fnc_allySkill = {
	params [["_unit", objNull, [objNull]], ["_sides", [], [[]]]];
	if (count VIOC_ALLY_PROFILE == 0) exitWith {false};
	if (isNull _unit || {!local _unit} || {isPlayer _unit} || {!alive _unit}) exitWith {false};
	if ((_unit getVariable ["vioc_ally", objNull]) isEqualTo _unit) exitWith {false};
	if (_sides isEqualTo []) then {_sides = call VIOC_fnc_allySides};
	if !((side group _unit) in _sides) exitWith {false};
	private _old = VIOC_ALLY_PROFILE apply {
		if ((_x select 0) == "aimingSpeed") then {_unit skill "general"} else {_unit skill (_x select 0)}
	};
	{
		_x params ["_sub", "_val"];
		_unit setSkill [_sub, ((_val - VIOC_ALLY_JITTER + random (2 * VIOC_ALLY_JITTER)) max (_old select _forEachIndex)) min 1];
	} forEach VIOC_ALLY_PROFILE;
	_unit setVariable ["vioc_ally", _unit];
	VIOC_ALLY_UNITS = VIOC_ALLY_UNITS + 1;
	true
};

//--- Grupos IA locales de un bando humano sin jugadores: nunca huyen (como los defensores de los pueblos).
//--- Se repite en cada pasada (es barato): cubre a los soldados que se unen despues y a los lideres reaparecidos.
VIOC_fnc_allyGroups = {
	params [["_sides", [], [[]]]];
	private _n = 0;
	{
		if (local _x && {(side _x) in _sides}) then {
			private _units = units _x;
			if (count _units > 0 && {({isPlayer _x} count _units) == 0}) then {
				_x allowFleeing 0;
				_n = _n + 1;
			};
		};
	} forEach allGroups;
	VIOC_ALLY_GROUPS = _n;
};

diag_log format ["VIOC_ai_allies: activo (habilidad %1, sin huida %2, pasada cada %3 s).", VIOC_ALLY_LEVEL, VIOC_ALLY_NOFLEE, VIOC_ALLY_PERIOD];

//--- Pasada periodica (la mision ya puso la habilidad de los lideres al iniciar; esto va despues).
waitUntil {sleep 1; !isNil "CTI_Init_Common"};
sleep 3;
while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
	private _sides = call VIOC_fnc_allySides;
	if (count _sides > 0) then {
		if (count VIOC_ALLY_PROFILE > 0) then {
			{
				if (local _x && {!((_x getVariable ["vioc_ally", objNull]) isEqualTo _x)} && {!isPlayer _x} && {(side group _x) in _sides}) then {
					[_x, _sides] call VIOC_fnc_allySkill;
				};
			} forEach allUnits;
		};
		if (VIOC_ALLY_NOFLEE) then {[_sides] call VIOC_fnc_allyGroups};
	};
	VIOC_ALLY_STATUS = [VIOC_ALLY_LEVEL, VIOC_ALLY_NOFLEE, VIOC_ALLY_SIDES, VIOC_ALLY_UNITS, VIOC_ALLY_GROUPS];
	sleep VIOC_ALLY_PERIOD;
};

class VIOC_AI_ALLY_SKILL {
		title = "VIOC: Habilidad de la IA de tu bando (el enemigo no cambia)";
		values[] = {0,1,2,3};
		texts[] = {"Igual que el enemigo (original)","Un poco mejor","Mejorada (recomendado)","Elite"};
		default = 2;
	};
	class VIOC_AI_ALLY_NOFLEE {
		title = "VIOC: La IA de tu bando nunca huye";
		values[] = {0,1};
		texts[] = {"No (original)","Si (recomendado)"};
		default = 1;
	};
